//! Files a project's build would write, written here because the build is
//! Node and nothing of Node runs (the user, 2026-11-11 08:41 ET). Ruling R3
//! (the integrator, 2026-11-11): only jQuery's trivial fixture file, nothing
//! else; one switch - the manifest's `generated` entry - turns it off.
//!
//! jQuery 4.0.0 build/tasks/qunit-fixture.js writes test/data/qunit-fixture.js
//! as:
//!
//!     "// Generated by build/tasks/qunit-fixture.js\n" +
//!     "QUnit.config.fixture = " +
//!         JSON.stringify( fixture.replace( /\r\n/g, "\n" ) ) +
//!     ";\n"
//!
//! where `fixture` is test/data/qunit-fixture.html read as UTF-8. No copy of
//! the generated file is published at the tag (the npm package `jquery@4.0.0`
//! carries dist/, src/ and six top-level files, no test/; jQuery hosts no
//! test page), so the tests below pin the transformation's rule -
//! ECMA-262 JSON.stringify of a String (QuoteJSONString) - instead of bytes
//! from upstream's build.

const std = @import("std");
const Allocator = std.mem.Allocator;
const Io = std.Io;

pub const Kind = enum { qunit_fixture };

pub const Error = error{ InvalidUtf8, OutOfMemory } || Io.Writer.Error;

/// ECMA-262 QuoteJSONString over UTF-8 text: `"`, `\`, and the C0 controls
/// escaped (the five with short forms as \b \t \n \f \r, the rest as \u00xx
/// in lowercase hex: UnicodeEscape), every other code point as it is,
/// U+2028 and U+2029 included. Text that is not UTF-8 is refused: Node
/// would have replaced it with U+FFFD on reading, which we do not imitate.
pub fn quoteJsonString(w: *Io.Writer, s: []const u8) Error!void {
    if (!std.unicode.utf8ValidateSlice(s)) return error.InvalidUtf8;
    try w.writeByte('"');
    for (s) |c| {
        switch (c) {
            0x08 => try w.writeAll("\\b"),
            0x09 => try w.writeAll("\\t"),
            0x0A => try w.writeAll("\\n"),
            0x0C => try w.writeAll("\\f"),
            0x0D => try w.writeAll("\\r"),
            '"' => try w.writeAll("\\\""),
            '\\' => try w.writeAll("\\\\"),
            0x00...0x07, 0x0B, 0x0E...0x1F => try w.print("\\u{x:0>4}", .{c}),
            else => try w.writeByte(c),
        }
    }
    try w.writeByte('"');
}

/// test/data/qunit-fixture.js from the bytes of test/data/qunit-fixture.html.
pub fn qunitFixture(gpa: Allocator, w: *Io.Writer, html: []const u8) Error!void {
    // fixture.replace( /\r\n/g, "\n" ): each CRLF pair, left to right; a
    // lone CR stays (and is escaped as \r).
    const normalized = try std.mem.replaceOwned(u8, gpa, html, "\r\n", "\n");
    defer gpa.free(normalized);
    try w.writeAll("// Generated by build/tasks/qunit-fixture.js\nQUnit.config.fixture = ");
    try quoteJsonString(w, normalized);
    try w.writeAll(";\n");
}

/// The bytes of a generated file of `kind` from its source's bytes.
pub fn generate(gpa: Allocator, kind: Kind, source: []const u8) Error![]u8 {
    var out: Io.Writer.Allocating = .init(gpa);
    errdefer out.deinit();
    switch (kind) {
        .qunit_fixture => try qunitFixture(gpa, &out.writer, source),
    }
    return out.toOwnedSlice();
}

const testing = std.testing;

test "QuoteJSONString: quote, backslash, the C0 controls; non-ASCII, U+2028 and DEL as they are" {
    var out: Io.Writer.Allocating = .init(testing.allocator);
    defer out.deinit();
    try quoteJsonString(&out.writer, "a\"b\\c\n\r\t\x08\x0c\x00\x01\x1b\x1f\x7f é \u{2028}\u{1F600}");
    // What JSON.stringify gives for that string in V8, SpiderMonkey and
    // JavaScriptCore alike (ECMA-262 25.5.2.3).
    try testing.expectEqualStrings("\"a\\\"b\\\\c\\n\\r\\t\\b\\f\\u0000\\u0001\\u001b\\u001f\x7f é \u{2028}\u{1F600}\"", out.written());
}

test "QuoteJSONString refuses text that is not UTF-8" {
    var out: Io.Writer.Allocating = .init(testing.allocator);
    defer out.deinit();
    try testing.expectError(error.InvalidUtf8, quoteJsonString(&out.writer, "a\xffb"));
}

test "the fixture file: its header, CRLF made LF, a lone CR kept, the trailing semicolon" {
    const bytes = try generate(testing.allocator, .qunit_fixture, "<div id=\"x\">\r\n\t<p>1</p>\r</div>\n");
    defer testing.allocator.free(bytes);
    try testing.expectEqualStrings(
        "// Generated by build/tasks/qunit-fixture.js\nQUnit.config.fixture = \"<div id=\\\"x\\\">\\n\\t<p>1</p>\\r</div>\\n\";\n",
        bytes,
    );
}

test "the fixture's string reads back as the normalized HTML (a JSON parser, not this encoder)" {
    const html = "<ol id=\"empty\"></ol>\r\n<form id=\"form\" action=\"formaction\">\r\n\t<label for=\"action\" id=\"label-for\">Action:</label>\r\n</form>\n\u{00e9}\"\\\x01";
    const bytes = try generate(testing.allocator, .qunit_fixture, html);
    defer testing.allocator.free(bytes);
    const head = "// Generated by build/tasks/qunit-fixture.js\nQUnit.config.fixture = ";
    try testing.expect(std.mem.startsWith(u8, bytes, head));
    try testing.expect(std.mem.endsWith(u8, bytes, ";\n"));
    const literal = bytes[head.len .. bytes.len - 2];
    const parsed = try std.json.parseFromSlice([]const u8, testing.allocator, literal, .{});
    defer parsed.deinit();
    const expected = try std.mem.replaceOwned(u8, testing.allocator, html, "\r\n", "\n");
    defer testing.allocator.free(expected);
    try testing.expectEqualStrings(expected, parsed.value);
}
